import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as dummy } from '@/primitives';
import { createNode as dummyText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry – a unit plane (will be scaled via config if needed)
  const geometry = new PlaneGeometry(1, 1);
  // Basic node material
  const material = new MeshBasicNodeMaterial();
  material.color = new Color(0xffffff);
  material.transparent = true; // allow for textures with alpha if any

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture if provided
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Store any timelines (none for this node but keep structure)
  const timelines = [];

  // Handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());

    // Dispose material resources
    if (material.map) material.map.dispose();
    material.dispose();

    // Dispose geometry
    geometry.dispose();

    // Dispose loaded texture if still referenced
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }
  };

  return root;
}
